    if(tab==='skills'){ for(const k in SK){ const l=level(k), nx=LV[l]||0; body.appendChild(el('div','hint','<b>'+name(SK[k])+'</b> Lv'+l+' · '+Math.floor(S.xp[k])+(nx?'/'+nx:''))); } const pr=Object.keys(S.prof).filter(k=>!/\d/.test(k)); if(pr.length) body.appendChild(el('div','hint','🎖 '+pr.join(' · '))); body.appendChild(el('div','hint','❤ '+S.hp+'/'+S.maxHp+' · ⚡'+Math.round(S.energy)+'/'+S.maxEnergy+' · 💧'+S.can+' · 🎒'+stacks()+'/'+S.bag)); }
