    S.can=canCapacity(); NPCS.forEach(n=>{ const f=fr(n.id); if(f.talk<S.absDay&&f.pts>0&&!f.dating&&S.absDay%3===0) f.pts=Math.max(0,f.pts-2); });
    festivalsToday(); dailyMail(); if(S.engaged&&S.absDay>=S.weddingDay){ S.spouse=S.engaged; S.engaged=null; S.pendingMsg.push({text:L('婚礼在广场举行,全镇都来了。今后你们一起住在小屋里。','The wedding is held in the plaza with the whole town there. From now on you share the cabin.')}); }
    if(S.spouse&&Math.random()<.3){ const b=['coffee','bread','fried_egg']; G.give('food',pick(b),1,true); S.pendingMsg.push({text:L('爱人给你做了早饭。','Your spouse made you breakfast.')}); }
