  function growth(){ for(const [k,tl] of S.tiles){ const [x,z]=k.split(',').map(Number), gh=inGreenhouse(x,z); if(tl.crop){ const c=CROPS[tl.crop.id]; const next=(S.day===SEASON_DAYS)?(S.season+1)%4:S.season; if(!gh&&!c.season.includes(next)){ tl.crop=null; continue; }
        if(tl.watered){ tl.crop.fresh=false; const sp=(tl.fert==='s1'&&Math.random()<.1)?2:1; if(tl.crop.cool){ if(--tl.crop.regrowing<=0){ tl.crop.cool=false; tl.crop.stage=c.days; } } else if(tl.crop.stage<c.days) tl.crop.stage=Math.min(c.days,tl.crop.stage+sp); } }
      if(!tl.crop&&!tl.watered&&!tl.sprinkler&&Math.random()<.1) { tl.tilled=false; tl.fert=null; } tl.watered=false; if(tl.crop) tl.crop.watered=false; }
    // crows take a crop when too many stand unguarded
    const crops=[...S.tiles.entries()].filter(([k,t])=>t.crop&&!inGreenhouse(...k.split(',').map(Number))); if(crops.length>=15&&Math.random()<.5){ const [k,t]=pick(crops), [x,z]=k.split(',').map(Number), guarded=S.placements.some(p=>p.id==='scarecrow'&&Math.hypot(p.x-x,p.z-z)<=8); if(!guarded){ t.crop=null; S.pendingMsg.push({text:L('乌鸦吃掉了一株作物。立个稻草人吧。','A crow ate one of your crops. Try a scarecrow.')}); } } }
  function orders(){ S.orders=S.orders.filter(o=>{ if(S.absDay>=o.day){ S.built[o.id]=(S.built[o.id]||0)+1; G.onBuilt&&G.onBuilt(o.id); S.pendingMsg.push({text:name(BUILDINGS[o.id].nm)+L(' 完工了!',' is finished!')}); return false; } return true; }); if(S.toolAway&&S.absDay>=S.toolAway.day) S.pendingMsg.push({text:L('工具升级好了,去铁匠铺取。','Your tool is ready at the blacksmith.')}); }
  function animalsDay(){ const hayNeed=S.animals.length; let fed=0; for(const a of S.animals){ const out=(S.season!==3&&S.weather==='clear'); const has=out||S.hay>0; if(!out&&S.hay>0) S.hay--; a.fr=clamp((a.fr||0)+(a.petted?15:-5)+(has?5:-20),0,1000); a.mood=has?1:0; a.petted=false; a.age=(a.age||0)+1; const def=ANIMALS[a.type]; if(has&&a.age%def.days===0&&a.age>=1){ const big=def.big&&a.fr>600&&Math.random()<a.fr/1500; const id=big?def.big:def.prof||def.prod, q=a.fr>800?2:a.fr>500?1:0; S.coop[id+(q?'~'+q:'')]=(S.coop[id+(q?'~'+q:'')]||0)+1; } } }
  G.petAnimal=()=>{ for(const a of S.animals){ const m=a.ref; if(m&&Math.hypot(m.A.x-player.pos.x,m.A.z-player.pos.z)<2.2&&!a.petted){ a.petted=true; a.fr=clamp((a.fr||0)+15,0,1000); toast('❤ '+name(ANIMALS[a.type].nm)); xp('farm',2); m.wait=1.5; return true; } } return false; };
  G.openCoopMenu=()=>modal(L('🐔 动物','🐔 Animals'),body=>{ body.appendChild(el('div','hint','🌾 '+S.hay+' · '+L('靠近动物按 E 抚摸','Press E by an animal to pet it'))); const g=el('div','grid'); body.appendChild(g); const keys=Object.keys(S.coop).filter(k=>S.coop[k]>0); const c=el('div','buy'+(keys.length?'':' dim')); c.innerHTML='<div class="em">🧺</div><div class="nm">'+L('收取产物','Collect')+'</div><div class="pr">'+keys.map(k=>META.of('product',k).em+S.coop[k]).join(' ')+'</div>'; c.onclick=()=>{ for(const k of keys){ if(G.give('product',k,S.coop[k],true)) delete S.coop[k]; } xp('farm',5*keys.length); G.openCoopMenu(); }; g.appendChild(c); S.animals.forEach(a=>{ const d=ANIMALS[a.type]; g.appendChild(el('div','buy','<div class="em">'+d.em+'</div><div class="nm">'+name(d.nm)+'</div><div class="pr">❤'+Math.round((a.fr||0)/200)+'/5 '+(a.mood?'😊':'😐')+'</div>')); }); });
  function crabsDay(){ for(const c of S.crabs){ if(!c.out&&(G.invCount('mat','bait')>0||S.prof.trapper)){ c.out=pick(['fish:carp','trash:seaweed','fish:chub','trash:algae']); } } }
  G.pullCrab=()=>{ for(const c of S.crabs){ if(c.out&&Math.hypot(c.x-player.pos.x,c.z-player.pos.z)<3){ const i=c.out.indexOf(':'); if(G.give(c.out.slice(0,i),c.out.slice(i+1))){ c.out=null; xp('fish',5); } return true; } } return false; };
  function dailyMail(){ if(S.absDay===1) mailTo('亲爱的新邻居:\n欢迎来到星星露谷。这是一点小心意。——镇长 里奥','Dear new neighbour:\nWelcome to StarVale. A little something to start you off. — Mayor Leo',['seed','parsnip',5]); if(S.day===1&&S.absDay>1) mailTo('新的季节开始了,别忘了更换当季种子。——小梅','A new season. Remember to change your seeds. — Mei'); const f=FESTIVALS.find(x=>x.s===S.season&&x.d===S.day+1); if(f) mailTo('明天是'+f.nm.zh+'!到广场来吧。'+f.nm.zh+':'+f.desc.zh,'Tomorrow is the '+f.nm.en+'! Come to the plaza. '+f.desc.en); const b=NPCS.find(n=>n.bday[0]===S.season&&n.bday[1]===S.day); if(b) S.pendingMsg.push({text:L('今天是 ','Today is ')+name(b.nm)+L(' 的生日',"'s birthday")}); if(S.mail.length) toast('✉️ '+L('有新邮件,去信箱看看','You have mail')); }
