  function themeFor(f){ return f<40?0:f<80?1:2; }
  function oreFor(f){ const r=Math.random(), rich=Math.min(.34,.14+f*.002); if(r<.02+f*.0004) return 'gem'; if(r<.05) return 'geode'; if(r<rich){ if(f>=80) return Math.random()<.2?'iridium':'gold_ore'; if(f>=40) return 'iron'; return 'copper'; } if(r<rich+.08) return 'coal'; return 'stone'; }
