  const MON={ slime:{hp:24,dmg:5,sp:1.5,col:0x6ad04a,xp:3,drop:'mat:slime',r:.5}, bug:{hp:18,dmg:6,sp:2.2,col:0x8a5a3a,xp:4,drop:'mat:bug_meat',r:.4}, crab:{hp:40,dmg:8,sp:1.3,col:0x6a6660,xp:6,drop:'mat:bug_meat',r:.55}, bat:{hp:24,dmg:6,sp:2.8,col:0x4a3a5a,xp:6,drop:'mat:bat_wing',r:.4,fly:1}, frost:{hp:60,dmg:10,sp:1.8,col:0x7ad8f0,xp:8,drop:'mat:slime',r:.55}, ghost:{hp:90,dmg:14,sp:2,col:0xd8d8f0,xp:12,drop:'ore:coal',r:.5,fly:1}, lava:{hp:140,dmg:18,sp:2.4,col:0xe84a2a,xp:15,drop:'ore:gold_ore',r:.6} };
  function monsterMesh(t){ const m=MON[t], G2=new THREE.Group(), mt=toonOf({color:m.col}); let b=new THREE.Mesh(new THREE.SphereGeometry(m.r,14,10),mt); b.scale.y=.8; b.position.y=m.r*.8; b.castShadow=true; G2.add(b); [-1,1].forEach(s=>{ const e=new THREE.Mesh(new THREE.SphereGeometry(m.r*.17,8,6),new THREE.MeshBasicMaterial({color:0x0a0a0a})); e.position.set(s*m.r*.36,m.r*.96,m.r*.76); G2.add(e); if(m.fly){ const w=new THREE.Mesh(new THREE.BoxGeometry(m.r*1.1,.03,m.r*.6),mt); w.position.set(s*m.r*1.1,m.r*.9,0); G2.add(w); G2.userData['w'+s]=w; } }); G2.userData.body=b; return G2; }
  M.floorSetup=f=>{ for(const n of M.nodes) M.stuff.remove(n.mesh); for(const m of M.mons) M.stuff.remove(m.mesh); if(M.ladder) M.stuff.remove(M.ladder.mesh); M.nodes=[]; M.mons=[]; M.ladder=null; M.theme=themeFor(f); const th=THEME[M.theme]; M.floor.material.color.setHex(th.floor); M.wall.material.color.setHex(th.wall); M.light.color.setHex(th.tint);
    if(f>S.mineMax){ S.mineMax=f; S.stats.floor=Math.max(S.stats.floor,f); questTick(); }
    const cnt=ri(16,26)+Math.min(10,f/8|0); for(let i=0;i<cnt;i++){ const a=rnd(0,6.28), r=Math.sqrt(Math.random())*14.5+1.5, x=Math.cos(a)*r, z=Math.sin(a)*r; if(Math.hypot(x,z)<3) continue; const k=oreFor(f), s=rnd(.55,1), mesh=nodeMesh(k,s); mesh.position.set(x,s*.3,z); M.stuff.add(mesh); M.nodes.push({mesh,x,z,kind:k,hp:k==='stone'?1:2+(f>=40?1:0)+(f>=80?1:0),s}); }
    if(f%10!==0||f===0){ const pool=f<40?['slime','bug','crab','bat']:f<80?['frost','bat','ghost']:['lava','ghost']; const n=ri(2,5)+Math.min(5,f/15|0); for(let i=0;i<n;i++){ const t=pick(pool), a=rnd(0,6.28), r=rnd(6,15), mesh=monsterMesh(t), x=Math.cos(a)*r, z=Math.sin(a)*r; mesh.position.set(x,0,z); M.stuff.add(mesh); const def=MON[t], sc=1+f*.012; M.mons.push({t,mesh,x,z,y:0,hp:def.hp*sc,dmg:def.dmg*sc|0,def,cd:0,bounce:rnd(0,6),kx:0,kz:0}); } }
    else { spawnLadder(0,6); M.chest=true; }
    player.pos.set(0,0,0); };
  function spawnLadder(x,z){ if(M.ladder) return; const g=new THREE.Group(), w=toonOf({color:0x8a6a44}); [-.32,.32].forEach(s=>{ const r=new THREE.Mesh(new THREE.BoxGeometry(.08,1.9,.08),w); r.position.set(s,.1,0); g.add(r); }); for(let i=0;i<6;i++){ const r=new THREE.Mesh(new THREE.BoxGeometry(.7,.07,.07),w); r.position.y=-.7+i*.32; g.add(r); } const h=new THREE.Mesh(new THREE.CircleGeometry(.9,18),new THREE.MeshBasicMaterial({color:0x050505})); h.rotateX(-Math.PI/2); h.position.y=.02; const o=new THREE.Group(); g.position.y=.9; o.add(h,g); o.position.set(x,0,z); M.stuff.add(o); M.ladder={mesh:o,x,z}; toast('🪜 '+L('出现了梯子','A ladder appears')); }
  M.enter=f=>{ S.inMine=true; S.mineLevel=f||1; world.visible=false; M.group.visible=true; G.onMine(true); M.floorSetup(S.mineLevel); toast(L('矿洞 · 第 ','Mine · Floor ')+S.mineLevel+L(' 层','')); G.renderStatus(); };
